
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_b88m_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_b88m", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.332727100795732e+00, -4.251100975783773e+00, -4.136815118050847e+00, -3.978692434903084e+00, -3.763628635322914e+00, -3.478218814894394e+00, -3.112541774656029e+00, -2.666843426524311e+00, -2.159947453093189e+00, -1.630721205146973e+00, -1.108737877369975e+00, -7.143097417223274e-01, -6.051530520613295e-01, -5.058287522725008e-01, -3.748989286261917e-01, -2.500045355335987e-01, -1.567992741834981e-01, -9.643216760732476e-02, -6.108002314671807e-02, -4.172437908535595e-02]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


